import{_ as e,H as a,f as l,i as n}from"./chunks/framework.BH2BK_3i.js";const d=JSON.parse('{"title":"25 | 两次翻译：把“基于HermesAgent的自动化测试”拆成技术方案","description":"","frontmatter":{},"headers":[{"level":2,"title":"背景： 加什么样的自动化测试","slug":"背景-加什么样的自动化测试","link":"#背景-加什么样的自动化测试","children":[]},{"level":2,"title":"第一次翻译：从一句话到完整设计","slug":"第一次翻译-从一句话到完整设计","link":"#第一次翻译-从一句话到完整设计","children":[{"level":3,"title":"AI 给的初版","slug":"ai-给的初版","link":"#ai-给的初版","children":[]},{"level":3,"title":"我反问的几个点","slug":"我反问的几个点","link":"#我反问的几个点","children":[]},{"level":3,"title":"完整设计文档成型了","slug":"完整设计文档成型了","link":"#完整设计文档成型了","children":[]}]},{"level":2,"title":"第二次翻译：从自研到建在 Hermes 上","slug":"第二次翻译-从自研到建在-hermes-上","link":"#第二次翻译-从自研到建在-hermes-上","children":[{"level":3,"title":"自研路径的真实成本","slug":"自研路径的真实成本","link":"#自研路径的真实成本","children":[]},{"level":3,"title":"Hermes 上的方案","slug":"hermes-上的方案","link":"#hermes-上的方案","children":[]},{"level":3,"title":"我反问的几个点","slug":"我反问的几个点-1","link":"#我反问的几个点-1","children":[]},{"level":3,"title":"AI 把方案收紧了","slug":"ai-把方案收紧了","link":"#ai-把方案收紧了","children":[]},{"level":3,"title":"完整方案文档成型了","slug":"完整方案文档成型了","link":"#完整方案文档成型了","children":[]}]},{"level":2,"title":"拿到这两份文档之后","slug":"拿到这两份文档之后","link":"#拿到这两份文档之后","children":[]},{"level":2,"title":"小结","slug":"小结","link":"#小结","children":[]},{"level":2,"title":"思考题","slug":"思考题","link":"#思考题","children":[]}],"relativePath":"ClaudeCode企业级老项目改造实战/25｜两次翻译：把“基于HermesAgent的自动化测试”拆成技术方案.md","filePath":"ClaudeCode企业级老项目改造实战/25｜两次翻译：把“基于HermesAgent的自动化测试”拆成技术方案.md","lastUpdated":1795530109000}'),p={name:"ClaudeCode企业级老项目改造实战/25｜两次翻译：把“基于HermesAgent的自动化测试”拆成技术方案.md"};function t(i,s,o,r,c,h){return a(),l("div",null,[...s[0]||(s[0]=[n(`<h1 id="_25-两次翻译-把-基于hermesagent的自动化测试-拆成技术方案" tabindex="-1">25 | 两次翻译：把“基于HermesAgent的自动化测试”拆成技术方案 <a class="header-anchor" href="#_25-两次翻译-把-基于hermesagent的自动化测试-拆成技术方案" aria-label="Permalink to &quot;25 | 两次翻译：把“基于HermesAgent的自动化测试”拆成技术方案&quot;">​</a></h1><p>你好，我是 Robert。</p><p>上一讲我们摸透了 Hermes，知道它能给我们什么、自己要写什么。但摸 Hermes 不是终点，只是手段。我们真正要做的事情是：给 RobustMQ 加 7×24 不间断的自动化混沌测试。</p><p>选 RobustMQ 作为这一讲的载体，有两个理由。一是它是个基础软件项目，质量要求是生产级的，自动化测试是真实需要，不是为了课程编出来的场景。二是社区里已经有 issue 在讨论这件事，多语言 SDK 兼容性、长时间运行稳定性这些问题，光靠人工测覆盖不到，真的需要一套 7×24 跑的自动化测试。如果有兴趣可以看一下下面几个资料：</p><ul><li><p><a href="https://robustmq.com/zh/Blogs/84" target="_blank" rel="noreferrer">https://robustmq.com/zh/Blogs/84</a></p></li><li><p><a href="https://robustmq.com/zh/Blogs/95" target="_blank" rel="noreferrer">https://robustmq.com/zh/Blogs/95</a></p></li><li><p><a href="https://github.com/robustmq/robustmq" target="_blank" rel="noreferrer">https://github.com/robustmq/robustmq</a></p></li></ul><p>那么今天这一讲，我们就把这件事从一句话“给 RobustMQ 加 7×24 不间断的自动化混沌测试”需求，翻译成可以动手的技术方案。每一次翻译都跑出一份完整文档，两份合起来，就是后续开发的单一事实源。</p><h2 id="背景-加什么样的自动化测试" tabindex="-1">背景： 加什么样的自动化测试 <a class="header-anchor" href="#背景-加什么样的自动化测试" aria-label="Permalink to &quot;背景： 加什么样的自动化测试&quot;">​</a></h2><p>简单讲一下背景，RobustMQ 是一个多协议消息中间件，支持 MQTT 这个主流协议和创新mq9 协议，定位生产级使用。作为一个开源的消息中间件项目，用户使用时的第一个问题不是功能够不够，而是敢不敢用：消息会不会丢、节点挂了能不能恢复、客户端 SDK 换个版本还能不能正常连。这些问题靠单元测试和常规集成测试覆盖不到，必须在真实的混乱条件下持续验证。所以现有测试有盲区。</p><p>单元测试和基础集成测试只能覆盖核心逻辑的正确性，但协议兼容性没有持续验证机制、故障场景没有系统化覆盖、长时间运行问题暴露不出来、组合场景几乎没碰。问题发现周期以月计，等用户踩坑反馈再修，节奏太慢，跟不上早期项目的迭代速度。所以需要有一个自动化的7×24 不间断的自动化混沌测试。</p><p>所以这个需求最开始就一句话：</p><ul><li>用 AI Agent 给 RobustMQ 实现一套 7×24 不间断跑混沌测试的系统，自动起集群、自动注入故障、自动调多语言 SDK 跑测试、自动收集日志、自动出报告。</li></ul><p>这句话听起来已经很具体了：5 个功能动词、1 个时间约束、1 个技术取向。看起来直接拆任务就能干。但接到这种需求当天就开始写代码的人，没一个交付得好。这句话里藏的事比说的多得多。</p><p>举几个它没说的：</p><ol><li><p>测什么协议、覆盖哪些 SDK 语言和版本？</p></li><li><p>故障注入到底是 kill 进程，还是网络延迟，还是磁盘填满？</p></li><li><p>测试报告给谁看？对内还是对外公开？</p></li><li><p>多语言 SDK 是预先写好的脚本，还是让 AI 现写？</p></li><li><p>频率怎么定？所有场景都跑一样频率，还是分级？</p></li></ol><p>这些事每一件都有几种合理选择，每种选择都会影响后面的技术方案长什么样。不先把它们拍清楚，直接进技术设计，后面会出现的情况是：写到一半发现某个假设不对、回头改方案、改完又发现另一处不对。绕一圈，几天就过去了。</p><p>所以接到一句话需求，第一件事不是拆方案，是先把需求本身拆完整。</p><p>这一讲的两次翻译就是做这件事：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E8%80%81%E9%A1%B9%E7%9B%AE%E6%94%B9%E9%80%A0%E5%AE%9E%E6%88%98/images/25/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E8%80%81%E9%A1%B9%E7%9B%AE%E6%94%B9%E9%80%A0%E5%AE%9E%E6%88%98/images/25/1.png" alt=""></a></p><p>第一次翻译的产物是一份“做什么、不做什么、给谁用、何时完成”的完整设计文档，和具体技术栈无关。第二次翻译才把完整设计落到 Hermes 上，产出 Skill 设计、Tool 清单、场景库、配置文件这些可以动手的东西。</p><p>两次翻译都让 Claude Code 帮我做，但每一次我都得提供方向。下面分别讲。</p><h2 id="第一次翻译-从一句话到完整设计" tabindex="-1">第一次翻译：从一句话到完整设计 <a class="header-anchor" href="#第一次翻译-从一句话到完整设计" aria-label="Permalink to &quot;第一次翻译：从一句话到完整设计&quot;">​</a></h2><p>我打开 Claude Code，扔给它一段提示词：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>帮我把这个一句话需求展开成完整的技术设计文档：用 AI Agent 给 RobustMQ</span></span>
<span class="line"><span>实现 7×24 不间断跑混沌测试的系统，自动起集群、注入故障、跑多语言 SDK、</span></span></code></pre></div><ul><li>收日志、出报告。</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>这一步先别谈具体技术框架，把&quot;为什么要做、做什么、不做什么、用什么思路、</span></span>
<span class="line"><span>覆盖什么场景、产出什么&quot;讲清楚。</span></span></code></pre></div><ul><li><p>有几个我自己一时拍不准的关键选择，你列出来给我看，每个给两三个选项和影响，我来拍。</p></li><li><p>不要复述，要展开。</p></li></ul><p>提示词四五句话，没有结构化清单，没有维度模板。好的提示词不是清单，是预设加余地。预设你已经想到的（目标、视角、问题域和技术栈分开），余地留给 AI 去补。提示词四五句话写得清楚，比模板化的二十行靠谱得多。</p><p>这段提示词里有三个关键设计：</p><ol><li><p>“先别谈具体技术框架”。把问题域和方案分开，这是这一讲的核心动作。如果不强调，AI立刻就会往 Hermes 上跳。</p></li><li><p>“几个我拍不准的选择，列出来给我”。这是这一步真正的灵魂。完整设计不是 AI 写出来的，是 AI 帮你列选项、人来拍出来的。AI 不知道你这个项目的定位是什么、你要不要公开测试报告、社区接受度如何，这些事只有你能拍。</p></li><li><p>“不要复述，要展开”。AI 偷懒的时候会把一句话改写成几句话就交差，这条话直接堵掉这种回答。</p></li></ol><h3 id="ai-给的初版" tabindex="-1">AI 给的初版 <a class="header-anchor" href="#ai-给的初版" aria-label="Permalink to &quot;AI 给的初版&quot;">​</a></h3><p>Claude Code 跑完，给了我一份完整的设计文档。</p><p>背景那段把 RobustMQ 面临的质量挑战讲清楚了，多协议、多语言 SDK、生产级要求。</p><p>目标那段提了三条，自动发现问题加速修复、公开测试过程建立社区信任、系统化解决协议兼容性。</p><p>系统设计那段最有价值。它把核心思路定在“混沌工程的思路，全流程 AI 自动化”：AI Agent是大脑，读取场景描述、自主决定执行顺序、根据中间结果动态调整、最终生成报告；工具集是手脚，执行集群操作、故障注入、日志收集。没有 hardcode 的执行流程，AI 驱动一切。</p><p>实现路径上，AI 的初版给的是 Claude API tool use + 若干 Python 工具函数。不引入LangGraph、CrewAI 这些 Agent 框架，理由是这些框架解决多 Agent 协作问题，本系统是单Agent + 固定工具集，直接用原生 tool use 更简单。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>工具集列了 7 个：cluster_start / cluster_stop / inject_fault / run_client /</span></span>
<span class="line"><span>get_logs / get_metrics / push_report。每个工具的签名和职责都写齐了。</span></span></code></pre></div><p>场景库那段给了完整的 MQTT 和 mq9 场景列表，按基础、故障、客户端异常、组合分类。每个场景一句话描述。</p><p>但我看完依然觉得有几处空洞。</p><h3 id="我反问的几个点" tabindex="-1">我反问的几个点 <a class="header-anchor" href="#我反问的几个点" aria-label="Permalink to &quot;我反问的几个点&quot;">​</a></h3><ol><li><p>场景的优先级没分。AI 列了几十个场景，但没说“哪些每次必跑、哪些每天跑、哪些每周跑”。混沌测试持续运行，频率分级是必须的，不然要么资源跑爆，要么覆盖度不够。</p></li><li><p>测试报告的公开度没定。报告对内给团队看，还是对外公开？这件事直接决定数据存在哪、有没有 Dashboard、要不要做信息脱敏。一句话需求里没说，完整设计里这条得有。</p></li><li><p>SDK 矩阵没系统化。AI 列了“多语言 SDK”，但具体覆盖哪些语言、每种语言哪几个版本、版本之间怎么切换，没讲。协议兼容性测试的核心就是这个矩阵，矩阵不清楚，测试就跑不出可信结果。</p></li></ol><p>我把这三条直接抛给 Claude Code：</p><ul><li>你这版有几处空洞：</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. 场景优先级没分。混沌测试持续跑，得有 P0/P1/P2 这种分级，</span></span>
<span class="line"><span>  按触发频率匹配。补一下。</span></span>
<span class="line"><span>2. 测试报告对内还是对外？这件事影响存储、Dashboard、脱敏一系列设计。</span></span>
<span class="line"><span>  给我两三个选项，我来拍。</span></span>
<span class="line"><span>3. SDK 矩阵不够系统。具体覆盖哪些语言、每种语言哪几个版本、</span></span>
<span class="line"><span>  怎么切换版本，展开。</span></span></code></pre></div><ul><li>别又冒新选择，把这版补完整。</li></ul><p>这一步是反问，不是追问。反问是“你这里漏了，补上”；追问是“你前面那段再讲讲”。AI 不会主动告诉你它漏了什么，得你自己有一份“完整设计文档该长什么样”的预期，拿这份预期去比对它给的版本，差了什么就反问什么。预期从哪来？从你工作经验里来。</p><p>Claude Code 跑完，三处全补上。</p><ol><li><p>场景库分级给了 P0 / P1 / P2：P0 是基础功能的最低保障线，任何 P0 失败立即报警；P1是故障场景和多语言基础覆盖；P2 是组合场景和完整 SDK 矩阵。</p></li><li><p>报告公开度给了三个选项：纯内部、对内详细对外摘要、完全公开。AI 还顺手给出第三个选项的工程价值，完全公开测试记录，反而是建立社区信任最有力的方式，比任何文档和声明都有说服力。这一句让我立刻拍了“完全公开”。</p></li><li><p>SDK 矩阵展开成完整的两张表：MQTT 协议 6 种语言加各自覆盖版本（Python paho-mqtt1.x/2.x、Go paho.mqtt.golang 1.x、Rust rumqttc 0.2x、Java Eclipse Paho 1.x 等），mq9协议随实现进度持续增加。</p></li></ol><h3 id="完整设计文档成型了" tabindex="-1">完整设计文档成型了 <a class="header-anchor" href="#完整设计文档成型了" aria-label="Permalink to &quot;完整设计文档成型了&quot;">​</a></h3><p>两轮拆解之后，我让 Claude Code 把所有产出整合成一份能拿出去给社区评审的完整技术设计文档。提示词关键点是“能拿出去给社区评审”，这给 AI 一个具体写作对象，文档不能太内部化，要能让一个不在团队里的工程师读懂“为什么做、做什么、怎么验证”。需要注意的是有一张协议兼容性归因表：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E8%80%81%E9%A1%B9%E7%9B%AE%E6%94%B9%E9%80%A0%E5%AE%9E%E6%88%98/images/25/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E8%80%81%E9%A1%B9%E7%9B%AE%E6%94%B9%E9%80%A0%E5%AE%9E%E6%88%98/images/25/2.png" alt=""></a></p><p>这张表后面会反复用，它把“测试发现问题”转换成“具体在哪里改”。完整设计文档可以直接看：<a href="https://robustmq.com/zh/Blogs/84%EF%BC%88%E5%9B%A0%E4%B8%BA%E5%86%85%E5%AE%B9%E7%AF%87%E5%B9%85%E6%9C%89%E9%99%90%EF%BC%8C%E6%88%91%E5%B0%B1%E4%B8%8D%E5%85%A8%E8%B4%B4%E8%BF%9B%E6%9D%A5%E4%BA%86%EF%BC%89%E3%80%82" target="_blank" rel="noreferrer">https://robustmq.com/zh/Blogs/84（因为内容篇幅有限，我就不全贴进来了）。</a></p><p>到这里，第一次翻译做完了。手上拿着的不再是一句话，是一份“为什么做、做什么、不做什么、按什么思路、覆盖哪些场景、产出什么”都讲清楚的文档。每个后续技术决策都能追溯到这份文档里的某条需求。</p><p>接下来本该把这份文档落到具体的技术栈上。但第二次翻译没我想象中那么直白，它从一个反问开始。</p><h2 id="第二次翻译-从自研到建在-hermes-上" tabindex="-1">第二次翻译：从自研到建在 Hermes 上 <a class="header-anchor" href="#第二次翻译-从自研到建在-hermes-上" aria-label="Permalink to &quot;第二次翻译：从自研到建在 Hermes 上&quot;">​</a></h2><p>第一次翻译的文档里，执行路径选了一条“自己撸”的路：用 Claude API tool use 实现 Agent 循环、用 Python 工具函数实现工具集、不引入 Agent 框架。</p><p>我把这版方案丢给 Claude Code，一开始的提示词是按部就班的：</p><ul><li>基于这份设计文档，给我一份具体的工程实施方案：目录结构、关键文件、依赖、部署方式、实施步骤。</li></ul><p>但提示词发出去前我停了一下。我 24 讲摸过 Hermes，Hermes 自带的能力清单跟我们这套系统需要的几乎全对得上。所以我把提示词改了：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>等一下。基于这份设计文档，但先别按&quot;自研&quot;的路径走。</span></span>
<span class="line"><span>我刚刚摸过 Hermes Agent。它自带：LLM 调用循环、Skill 调度、Cron 触发、</span></span>
<span class="line"><span>跨会话记忆、多通道接入、安全沙箱。这套系统需要的&quot;工具函数 + 框架 + 通道</span></span>
<span class="line"><span>+ 持久化&quot;里，框架/通道/持久化 Hermes 都有了。</span></span></code></pre></div><ul><li>帮我对比两个路径：</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. 按设计文档原方案，自研 Claude API tool use + Python 工具</span></span>
<span class="line"><span>2. 把这套系统建在 Hermes 之上，作为一组 Skills 跑</span></span></code></pre></div><ul><li>每个路径分别要做什么、各自的工程量、各自的演进空间。</li></ul><p>这是第二次翻译的灵魂。不是把方案落到技术栈上，是先反问“我选错路径了吗”。第一次翻译产物里“自研”是 AI 顺着我的提问给的，但我刚摸过 Hermes，该用这份认知去质疑这个路径。</p><h3 id="自研路径的真实成本" tabindex="-1">自研路径的真实成本 <a class="header-anchor" href="#自研路径的真实成本" aria-label="Permalink to &quot;自研路径的真实成本&quot;">​</a></h3><p>Claude Code 跑完，给的对照表很扎实：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E8%80%81%E9%A1%B9%E7%9B%AE%E6%94%B9%E9%80%A0%E5%AE%9E%E6%88%98/images/25/3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E8%80%81%E9%A1%B9%E7%9B%AE%E6%94%B9%E9%80%A0%E5%AE%9E%E6%88%98/images/25/3.png" alt=""></a></p><p>工具函数是冰山一角。一个生产可用的 AI Agent 系统，框架、调度、上下文、触发、通道、沙箱、持久化加起来比工具函数本身大好几倍。这些 Hermes 全部自带。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E8%80%81%E9%A1%B9%E7%9B%AE%E6%94%B9%E9%80%A0%E5%AE%9E%E6%88%98/images/25/4.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E8%80%81%E9%A1%B9%E7%9B%AE%E6%94%B9%E9%80%A0%E5%AE%9E%E6%88%98/images/25/4.png" alt=""></a></p><p>更关键的是，Claude Code 还给了一条演进收益：把核心建在 Hermes 之上，未来质量保障流程不只是“跑测试”。团队成员可以通过飞书直接给 Hermes 发指令，“上次失败的网络抖动场景再跑一次”或“今天有什么新问题”，Hermes 把指令翻译成 Skill 调用，把结果通过原通道返回。测试系统从“自动跑”演进成“AI 助理”，这是单纯的 Python 脚本系统给不出的可能性。</p><p>到这一步，选什么路径已经不需要再讨论。我把第二次翻译的方向定下来：基于 Hermes 重写。</p><h3 id="hermes-上的方案" tabindex="-1">Hermes 上的方案 <a class="header-anchor" href="#hermes-上的方案" aria-label="Permalink to &quot;Hermes 上的方案&quot;">​</a></h3><p>提示词：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>方向定了，基于 Hermes 重写技术方案。需要包括：</span></span>
<span class="line"><span>1. 整体架构和部署方式</span></span>
<span class="line"><span>2. Skill 怎么设计？套件还是多个独立 Skill？目录结构什么样？</span></span>
<span class="line"><span>3. 工具函数全部映射成 Skill 里的 Tool，每个 Tool 怎么实现？</span></span>
<span class="line"><span>4. 场景库怎么放？怎么让 Agent 读？</span></span>
<span class="line"><span>5. 触发机制</span></span>
<span class="line"><span>6. 报告系统(GitHub 公开仓库 + Dashboard)</span></span>
<span class="line"><span>7. 关键决策记录(每条带选定方案和理由)</span></span>
<span class="line"><span>8. 实施步骤(按依赖顺序)</span></span>
<span class="line"><span>记得结构化的东西用代码生成，JSON 别交给LLM 写。</span></span></code></pre></div><p>提示词里塞了几样硬约束：</p><ul><li><p>Hermes 的能力边界（白嫖 / 开发分割）是 24 讲建立的认知，直接复用。</p></li><li><p>JSON 别交给 LLM 写是 24 讲跑出来的硬规则。</p></li><li><p>至少包括 8 节内容，是我对方案文档最低限度的预期。</p></li></ul><p>Claude Code 给了一份相当扎实的初版方案。</p><p>Skill 套件设计：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>7 个工具函数全部映射成同一个 Skill 套件 robustmq-chaos-test 下的 Tools。核心理由是</span></span></code></pre></div><p>它们共享同一个上下文（场景描述、集群状态、测试进度），由 Agent 串联调用最自然。如果拆成 7 个独立 Skill，跨 Skill 的上下文管理会成为新的负担。</p><p>目录结构：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>~/.hermes/skills/robustmq-chaos-test/</span></span>
<span class="line"><span>├── SKILL.md                    # 给 Agent 的场景描述和工具说明</span></span>
<span class="line"><span>├── tools/</span></span>
<span class="line"><span>│   ├── cluster.py              # cluster_start / cluster_stop</span></span>
<span class="line"><span>│   ├── chaos.py                # inject_fault</span></span>
<span class="line"><span>│   ├── client.py               # run_client(多语言 SDK 调度)</span></span>
<span class="line"><span>│   ├── observability.py        # get_logs / get_metrics</span></span>
<span class="line"><span>│   └── report.py               # push_report</span></span>
<span class="line"><span>├── scenarios/                  # 场景库(自然语言描述)</span></span>
<span class="line"><span>│   ├── mqtt/</span></span>
<span class="line"><span>│   └── mq9/</span></span>
<span class="line"><span>├── templates/</span></span>
<span class="line"><span>│   └── report.md.j2            # 报告 Markdown 模板</span></span>
<span class="line"><span>└──config yml</span></span>
<span class="line"><span># SDK 版本矩阵</span></span>
<span class="line"><span>Chaosd 端点</span></span></code></pre></div><ul><li>报告仓库地址</li></ul><p>SKILL.md 是 Agent 真正读到的“场景描述”。它告诉 Agent 这个 Skill 是干什么的、有哪些Tool 可用、什么时候该用哪个、报告应该长什么样。</p><p>关键 Tool 的设计：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>cluster_start 不引入 Docker，直接 spawn 多个 RobustMQ 进程。每个节点用独立端</span></span>
<span class="line"><span>口和数据目录，数据目录用临时目录，cluster_stop 时清理。这一条决策极简，单机环</span></span></code></pre></div><ul><li>境跑混沌测试，Docker 反而增加复杂度。</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>inject_fault 以 Chaosd（Chaos Mesh 单机版）为主，tc / kill 等系统命令为补充。</span></span></code></pre></div><ul><li>Chaosd 提供 HTTP API，函数封装调用，参数对齐 Chaosd schema。</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>run_client 多语言 SDK 调度的关键设计是，服务器上预装多语言运行时和版本管理工</span></span></code></pre></div><ul><li>具（pyenv / gvm / rustup / sdkman / nvm），Skill 里通过版本管理工具切换，不用Docker。单机环境足够，启动快。</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>push_report 直接 git clone / commit / push 到 GitHub 公开仓库，不调 GitHub API，比</span></span></code></pre></div><ul><li>API 调用更简单可控。</li></ul><h3 id="我反问的几个点-1" tabindex="-1">我反问的几个点 <a class="header-anchor" href="#我反问的几个点-1" aria-label="Permalink to &quot;我反问的几个点&quot;">​</a></h3><p>这版方案比第一次翻译那一版成熟得多。AI 自己已经会“列选项 + 给建议”，不再被动等我拍。但我看完依然觉得几处可以收紧。</p><ol><li><p>Skill 套件粒度有歧义。AI 说放一个套件下，理由是共享上下文。但如果未来要扩展Claude Code 深度分析 Skill，它跟 chaos-test 共享上下文吗？这个边界得讲清楚，不然以后再加一个 Skill 又要回头重构。</p></li><li><p>故障注入选型留白太多。AI 给了 Chaosd 主 + tc 补，但没说什么时候该用哪个。“极简场景用 tc” 这一句太模糊，工程师看了不知道判断标准。</p></li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GitHub 凭据怎么管没说。push_report 要写仓库，凭据放哪、怎么轮换、Skill 里怎么读</span></span></code></pre></div><ul><li>到，这些是 7×24 系统最容易翻车的地方。</li></ul><p>把这三条直接抛给 Claude Code：</p><ul><li>你这版有几处可以再收紧：</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. Skill 套件粒度：这次放一个套件下没问题，但未来加 Claude Code 深度</span></span>
<span class="line"><span>  分析 Skill 时，边界怎么划？给个原则。</span></span>
<span class="line"><span>2. 故障注入 Chaosd vs tc 的选择标准模糊。给个判断：什么场景用哪个。</span></span>
<span class="line"><span>3. GitHub 凭据怎么管？Deploy Key 还是 PAT？放哪？Skill 里怎么读？</span></span></code></pre></div><ul><li>补这三条，别又冒新决策。把这版收紧。</li></ul><p>提示词最后那句“别又冒新决策，把这版收紧”很关键。第一次翻译的两轮都在展开，每一轮都让 AI 列新选项。但第二次翻译已经到方案阶段，不能再发散，只能收敛。如果不点这句，AI又会一边补、一边给你冒新决策点，方案永远定不下来。</p><h3 id="ai-把方案收紧了" tabindex="-1">AI 把方案收紧了 <a class="header-anchor" href="#ai-把方案收紧了" aria-label="Permalink to &quot;AI 把方案收紧了&quot;">​</a></h3><p>Claude Code 跑完，三条全接住，而且没冒新决策。</p><ol><li><p>Skill 边界原则：一个 Skill 套件等于一个独立的工作流。chaos-test 是“跑混沌测试”这个工作流；未来 Claude Code 深度分析是“分析失败报告”这个独立工作流，两者通过共享报告仓库联动，但 Skill 内部隔离，不共享 tools 目录。这一条让未来扩展有了明确的切线。</p></li><li><p>故障注入选型标准：Chaosd 用于所有需要精确控制的故障（进程级 kill 信号、网络精确延迟分布、磁盘 I/O 限速、时钟穿越）；tc / kill 用于极简快验证场景，临时拉起验证一下逻辑就行。判断标准是“故障是否需要被精确测量和回放”，需要就用 Chaosd，只是验证可达性就用系统命令。</p></li><li><p>GitHub 凭据：用 Deploy Key，只授写权限到 test-reports 单一仓库。私钥放在服务器</p></li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>~/.ssh/test-reports-deploy，Skill 里通过 GIT_SSH_COMMAND 环境变量指定使用</span></span></code></pre></div><ul><li>这个 key 做 git push，不进 Hermes 的 .env，也不进版本库。这一条接住了 24 讲那条硬规则：7×24 无人值守最容易翻车的就是凭据和 allowlist。</li></ul><p>这一轮收得很紧，没冒新决策，该补的全补上。</p><h3 id="完整方案文档成型了" tabindex="-1">完整方案文档成型了 <a class="header-anchor" href="#完整方案文档成型了" aria-label="Permalink to &quot;完整方案文档成型了&quot;">​</a></h3><p>最后一步，让 Claude Code 把所有讨论整合成一份和设计文档对称的完整技术方案文档。提示词显式列出：对照表 + 7 个 Tool 实现要点 + 场景库分级 + 触发机制 + GitHub 凭据 + 关键决策。不点这些 AI 会漏，因为它默认从最近对话回忆，而不是把整个反问链路重新组织。跑出来的文档里最值钱的是这几个东西。</p><ol><li><p>Skill 套件目录结构：8 行树形结构。看着简单，但每一行都对应一条决策：tools/ 多个文件而不是一个，scenarios/ 按协议分目录，templates/ 用 Jinja2，config.yml 和 SKILL.md 分开。每条都有理由，不是随便排的。</p></li><li><p>关键决策记录：8 条，每条带选定方案和理由。</p></li></ol><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E8%80%81%E9%A1%B9%E7%9B%AE%E6%94%B9%E9%80%A0%E5%AE%9E%E6%88%98/images/25/5.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E8%80%81%E9%A1%B9%E7%9B%AE%E6%94%B9%E9%80%A0%E5%AE%9E%E6%88%98/images/25/5.png" alt=""></a></p><p>这张表是后面所有开发的硬约束。cluster_start 怎么实现来自“单机 + 不用 Docker”；run_client 怎么实现来自“本地版本管理”；push_report 怎么实现来自“git push 用 DeployKey”。</p><p>实施步骤按依赖顺序拆，先环境准备，再搭 Skill 骨架，然后按 Tool 依赖顺序实现（cluster →observability → run_client → inject_fault → push_report），再写场景库，最后跑通完整闭环和报告系统。每一步产出都能独立验证，卡在哪一步立刻能定位。</p><p>完整方案文档如下：<a href="https://robustmq.com/zh/Blogs/95%EF%BC%88%E5%9B%A0%E4%B8%BA%E5%86%85%E5%AE%B9%E7%AF%87%E5%B9%85%E6%9C%89%E9%99%90%EF%BC%8C%E6%88%91%E5%B0%B1%E4%B8%8D%E5%85%A8%E8%B4%B4%E8%BF%9B%E6%9D%A5%E4%BA%86%EF%BC%89%E3%80%82" target="_blank" rel="noreferrer">https://robustmq.com/zh/Blogs/95（因为内容篇幅有限，我就不全贴进来了）。</a></p><p>到这里，第二次翻译做完了。手上拿着的不再是“在 Hermes 上做一个混沌测试系统”这种模糊方向，是一份可以分配给具体工程师按依赖顺序开干的方案。</p><h2 id="拿到这两份文档之后" tabindex="-1">拿到这两份文档之后 <a class="header-anchor" href="#拿到这两份文档之后" aria-label="Permalink to &quot;拿到这两份文档之后&quot;">​</a></h2><p>走完两次翻译，我手上有两份真实的文档。一份是完整设计文档，讲清楚为什么做、做什么、按什么思路。一份是完整方案文档，讲清楚怎么具体落到 Hermes 上。</p><p>这两份文档之间有一条清晰的因果链。设计文档里“协议兼容性是核心命题”直接决定了方案文</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>档里 run_client Tool 的多语言矩阵设计。设计文档里“测试记录完全公开建立社区信任”直</span></span>
<span class="line"><span>接决定了方案文档里 push_report 提交到 GitHub 公开仓库 + Quality Dashboard 静态读取</span></span></code></pre></div><p>的设计。设计文档里“P0 / P1 / P2 场景分级”直接决定了方案文档里 cron.yml 那 4 条不同频率的触发配置。</p><p>这条因果链是这两份文档真正的价值。不是文档本身有多漂亮，而是后续每一行代码、每一个配置、每一个判断，都能追溯到上游某条需求决策。开发过程中如果有人问“为什么 run_client要支持 SDK 版本切换”，答案不是“我觉得这样好”，是“因为设计文档里的协议兼容性目标这么定的”。如果某天需要改协议兼容性策略，你也能立刻知道下游有哪些 Tool 会受影响。</p><p>接下来开发的时候，这两份文档就是单一事实源。不是开发完成后再补的文档，是开发过程中的硬约束。任何代码偏离了文档的决定，要么改代码，要么改文档，然后回来重新对齐。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><p>这一讲教的就是接到一句话需求那一阵子该做什么。一句话需求很危险，因为它藏的事比说的多。</p><p>接到这种需求，第一件事是把它翻译两次。</p><ul><li><p>第一次翻译是从一句话到完整设计文档，让 AI 帮你穷举该拍的事，你来拍方向。产物和技术栈无关，讲清楚为什么做、做什么、不做什么、按什么思路。</p></li><li><p>第二次翻译才把完整设计落到具体技术栈上，跑出一份能开干的方案文档。产出 Skill 设计、Tool 实现、场景库、触发配置这些可以动手的东西。</p></li></ul><p>第二次翻译有个容易被忽视的环节：先反问“路径选对了吗”。第一次翻译产物里的执行路径，可能是 AI 顺着你的提问随手给的，不是认真比较过的最优路径。这一步反问，就是把 24 讲建立的工具认知拿出来用，你刚摸过的那个开源项目，可能已经把方案里 80% 的工程都做了，你不用自己撸。</p><p>每次翻译都不是 AI 一次性出方案，而是反问到 AI 收敛为止。AI 的价值是穷举该拍的事，你的价值是拍方向。提示词不需要很长，预设你已经想到的，余地留给 AI 去补，几句话写得清楚就够了。</p><p>写完两份文档，第一件事其实是放下。第二天早上再看一遍，你常常会发现某个决策当时拍得太草率，趁还没动手赶紧改回来。真正动手前，留一晚给方案沉淀，这条经验比方法论本身值钱。</p><p>所以接到需求当天就开始写代码的人，没一个交付得好。理由不是“先写文档显得专业”，而是写文档的过程本身就是把需求里所有藏着的事拍清楚的过程。不拍清楚就动手，等于把代码当成需求的探索工具，代价是改代码远比改文档贵。</p><h2 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h2><p>回想你最近一次接到一句话需求的经历，比如做个监控系统、加个权限模块、接个支付通道。如果用这一讲的“两次翻译”打法重做一遍，你的第二次翻译里那个“路径选对了吗”的反问，会反问什么？有没有一个你已经摸过、但当时没想到要用上的工具？</p><p>欢迎在留言区写下你的版本，我们一起把这套打法磨得更趁手。如果今天的课程让你有所收获，也欢迎转发给有需要的朋友，邀请他来一起学习，我们下节课再见！</p>`,134)])])}const g=e(p,[["render",t]]);export{d as __pageData,g as default};
